import{_ as S,a0 as p,w as D,s as O,ao as l,I as a,x as o,a1 as r,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"FreeDOS： 已经积极开发了 23 年的 DOS | LCTT x X-CMD","titleTemplate":false,"description":"FreeDOS： 已经积极开发了 23 年的 DOS | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FreeDOS： 已经积极开发了 23 年的 DOS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FreeDOS： 已经积极开发了 23 年的 DOS | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170629 4 cool facts you should know about FreeDOS","title":"FreeDOS： 已经积极开发了 23 年的 DOS","tag":"201707","desc":""},"relativePath":"201707/20170629 4 cool facts you should know about FreeDOS.md","filePath":"[post].md"}'),i={name:"201707/20170629 4 cool facts you should know about FreeDOS.md"};function n(d,e,u,f,m,F){const t=p("Link");return D(),O("div",null,[e[16]||(e[16]=l('<h1 id="freedos-已经积极开发了-23-年的-dos" tabindex="-1">FreeDOS： 已经积极开发了 23 年的 DOS <a class="header-anchor" href="#freedos-已经积极开发了-23-年的-dos" aria-label="Permalink to “FreeDOS： 已经积极开发了 23 年的 DOS”">​</a></h1><blockquote><p>23 年后，FreeDOS 仍在积极开发，并将 MS-DOS 的生命延长了几年</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/wings_freedos_game.jpg?itok=3O_GB-7o" alt="4 cool facts you should know about FreeDOS " title="4 cool facts you should know about FreeDOS "></p><p>在 90 年代早期，我是一位 DOS 的 “资深用户”。我用 DOS 做任何事，甚至写我自己的工具来扩展 DOS 命令行。当然，我们有 Microsoft Windows，但是如果你还记得当时的计算机，Windows 3.1 并不是那么好，我更喜欢在 DOS 中工作。</p><p>你可能会理解，在 1994 年，当微软（在科技杂志的采访中）宣布下一个版本的 Windows 将会取消 MS-DOS 时，我感到有些困惑和不安。我想：“如果 Windows 3.2 或 4.0 看起来像 Windows 3.1 一样，我不想用它了。” 我四处选择，并决定如果 DOS 要继续下去的话，那么需要有人创建一个 DOS，在 MS-DOS 消失的时候，让每个人都可以使用它。</p><p>因此在 1994 年 6 月 29 日，我在 Usenet 讨论组写了一个信息，宣布了新的 “free DOS” 项目：</p><blockquote><p>几个月前，我发表了一篇关于启动公共领域版本的 DOS 的文章。当时对此的普遍支持是很强烈的，并且很多人同意这个声明，“开始编写！”</p><p>所以，我要……</p><p>宣布首次尝试制作 PD-DOS。我写了一份描述这样一个项目的目标和工作纲要的“清单”，以及一份“任务清单”，展示了需要编写些什么。我会在这里发贴，让我们进行讨论。</p></blockquote>',7)),a("p",null,[e[1]||(e[1]=o("今天，已经是 23 年之后了，",-1)),r(t,{href:"https://opensource.com/article/17/6/www.freedos.org"},{default:s(()=>[...e[0]||(e[0]=[o("FreeDOS",-1)])]),_:1}),e[2]||(e[2]=o(" 仍在变得更强大！",-1))]),e[17]||(e[17]=l('<p>我们继续发布有新功能和特性的版本。我们的 FreeDOS 1.2 发布于 2016 年 12 月 25 日，这证明很多人喜欢使用和在 FreeDOS 上工作。当我回顾我们的历史，有一个你应该知道的关于 FreeDOS 的很酷的事实列表：</p><h3 id="可以立即开始的软件开发" tabindex="-1">可以立即开始的软件开发 <a class="header-anchor" href="#可以立即开始的软件开发" aria-label="Permalink to “可以立即开始的软件开发”">​</a></h3><p>在原始的 DOS 中，很难做任何编程。DOS 提供了一个简单的 BASIC 解释器，一些用户可以用 DEBUG 做些精巧的事情，但是你不能在 DOS 中做真正编程的事情。在 FreeDOS 中，有许多不同的工具做软件开发：编译器、汇编器、调试器、解释器和编写脚本。在你安装 FreeDOS 之后，你可以立即用 C、汇编、Pascal、Perl 和几种其他语言编写代码。</p><h3 id="浏览-web" tabindex="-1">浏览 web <a class="header-anchor" href="#浏览-web" aria-label="Permalink to “浏览 web”">​</a></h3><p>DOS 是一个老式系统，并且原本不支持开箱即用的网络。通常，你必须安装硬件的设备驱动程序才能连接到网络，一般是像 IPX 这样的简单网络。只有很少的系统会支持 TCP/IP。</p><p>在 FreeDOS 中，我们不仅包含了 TCP/IP 网络栈，我们还包含了让你浏览 web 的工具和程序。使用 Dillo 作为图形 web 浏览体验，或则使用 Lynx 以纯文本形式浏览 web。如果你只想要抓取 HTML 代码并自己操作，使用 Wget 或者 Curl。</p><h3 id="玩很棒的-dos-游戏" tabindex="-1">玩很棒的 DOS 游戏 <a class="header-anchor" href="#玩很棒的-dos-游戏" aria-label="Permalink to “玩很棒的 DOS 游戏”">​</a></h3><p>我们知道很多的人安装 FreeDOS 来玩经典的 DOS 游戏，运行古老的商业程序或者做嵌入式开发。使用 FreeDOS 的许多人只是拿来玩游戏，那对我们来说是件很酷的事，因为一个游戏很老并不意味着它很无趣。DOS 有许多很棒的游戏！安装你最喜欢的经典游戏，你会玩得很开心。</p><p>因为有如此多的人使用 FreeDOS 来玩游戏，我们现在包含了不同的 DOS 游戏。FreeDOS 1.2 包含了第一人称射击游戏像 FreeDOOM、街机射击像 Kiloblaster、飞行模拟器像 Vertigo 等等。我们目标是为每人提供一些东西。</p><h3 id="freedos-现在已经比-ms-dos-活的更久了" tabindex="-1">FreeDOS 现在已经比 MS-DOS 活的更久了 <a class="header-anchor" href="#freedos-现在已经比-ms-dos-活的更久了" aria-label="Permalink to “FreeDOS 现在已经比 MS-DOS 活的更久了”">​</a></h3><p>微软在 1981 年 8 月发布了 MS-DOS 1.0。13 年之后，微软在 1995 年 8 月发布 Windows 95 后抛弃了 MS-DOS，虽然 MS-DOS 直到 2000 年 9 月之前一直存在。总的来说，MS-DOS 是一件已经存在了 19 年的东西。</p><p>我们在 1994 年 6 月宣布了 FreeDOS，并且在同年的 9 月发布了第一个 Alpha 版本。因此 FreeDOS 已经大约有 23 年了，比微软的 MS-DOS 还多了几年。确实我们在 FreeDOS 上努力的时间已经比 MS-DOS 更长了。而 FreeDOS 还将继续保持强大。</p><p>FreeDOS 与其他 DOS 另外一个重要的不同是_它仍在开发中_。我们有一个积极的开发者社区，并一直在寻找新人来帮助。请加入社区并帮助构造新的 FreeDOS 版本吧。</p><p>（题图： FreeDOS）</p><hr><p>作者简介：</p><p>Jim Hall - 我是 FreeDOS 项目的创始人和协调者。我还担任 GNOME 基金董事会董事。在工作中，我是明尼苏达州拉姆齐县的首席信息官。在业余时间，我致力于开源软件的可用性，并通过 Outreachy（之前针对妇女的 GNOME Outreach 项目）指导 GNOME 中的可用性测试。</p><hr>',18)),a("p",null,[e[4]||(e[4]=o("via: ",-1)),r(t,{href:"https://opensource.com/article/17/6/freedos-still-cool-today"},{default:s(()=>[...e[3]||(e[3]=[o("https://opensource.com/article/17/6/freedos-still-cool-today",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("作者：",-1)),r(t,{href:"https://opensource.com/users/jim-hall"},{default:s(()=>[...e[5]||(e[5]=[o("Jim Hall",-1)])]),_:1}),e[9]||(e[9]=o(" 译者：",-1)),r(t,{href:"https://github.com/geekpi"},{default:s(()=>[...e[6]||(e[6]=[o("geekpi",-1)])]),_:1}),e[10]||(e[10]=o(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=o("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原创编译，",-1)),r(t,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[o("Linux中国",-1)])]),_:1}),e[15]||(e[15]=o(" 荣誉推出",-1))])])}const h=S(i,[["render",n]]);export{w as __pageData,h as default};
